import {registerCardComponent} from "@pihanga2/core";

import {ResizableColumnsComponent} from "./resizableColumns.component";
import {RESIZABLE_COLUMNS_CARD} from "./resizableColumns.types";

export * from "./resizableColumns.types";

registerCardComponent({
  name: RESIZABLE_COLUMNS_CARD,
  component: ResizableColumnsComponent,
});

import * as React from "react";
import {Card, type PiCardProps} from "@pihanga2/core";
import clsx from "clsx";

import "./resizableColumns.css";
import type {ResizableColumnsProps} from "./resizableColumns.types";

const DEFAULT_MIN_PERCENT = 10;

type ParsedUnit = {type: "px" | "pct" | "fr"; value: number};

function parseColumnWidths(
  widths: string[] | undefined,
  count: number,
  containerPx: number,
): number[] {
  if (!widths?.length || widths.length !== count) {
    return new Array(count).fill(100 / count);
  }

  const parsed: ParsedUnit[] = widths.map((w) => {
    const s = w.trim();
    if (s.endsWith("px"))
      return {type: "px", value: Math.max(0, parseFloat(s))};
    if (s.endsWith("%"))
      return {type: "pct", value: Math.max(0, parseFloat(s))};
    if (s.endsWith("fr"))
      return {type: "fr", value: Math.max(0, parseFloat(s))};
    return {type: "fr", value: 1};
  });

  const totalPxAsPct =
    containerPx > 0
      ? parsed.reduce(
          (s, p) => s + (p.type === "px" ? (p.value / containerPx) * 100 : 0),
          0,
        )
      : 0;
  const totalExplicitPct = parsed.reduce(
    (s, p) => s + (p.type === "pct" ? p.value : 0),
    0,
  );
  const remainingPct = Math.max(0, 100 - totalPxAsPct - totalExplicitPct);
  const totalFr = parsed.reduce(
    (s, p) => s + (p.type === "fr" ? p.value : 0),
    0,
  );

  const result = parsed.map((p) => {
    if (p.type === "px")
      return containerPx > 0 ? (p.value / containerPx) * 100 : 100 / count;
    if (p.type === "pct") return p.value;
    return totalFr > 0
      ? (p.value / totalFr) * remainingPct
      : remainingPct / count;
  });

  const total = result.reduce((s, v) => s + v, 0);
  return total > 0
    ? result.map((v) => (v / total) * 100)
    : new Array(count).fill(100 / count);
}

const clamp = (v: number, min: number, max: number) =>
  Math.min(max, Math.max(min, v));

export const ResizableColumnsComponent = (
  props: PiCardProps<ResizableColumnsProps>,
): React.ReactNode => {
  const {
    cardName,
    columnCards = [],
    columnWidths,
    minColumnPercent = DEFAULT_MIN_PERCENT,
    className,
    dividerClassName,
  } = props;

  const count = columnCards.length;

  // Equal split as the initial state — useLayoutEffect overwrites before paint.
  const [panePercents, setPanePercents] = React.useState<number[]>(() =>
    new Array(count).fill(100 / count),
  );
  const panePercentsRef = React.useRef(panePercents);
  const containerRef = React.useRef<HTMLDivElement | null>(null);
  const dragCleanupRef = React.useRef<(() => void) | null>(null);

  // Parse columnWidths once the container is mounted so px values can be resolved.
  React.useLayoutEffect(() => {
    if (!containerRef.current) return;
    const width = containerRef.current.getBoundingClientRect().width;
    const next = parseColumnWidths(columnWidths, count, width);
    panePercentsRef.current = next;
    setPanePercents(next);
  }, [columnWidths, count]);

  // Cleanup any in-progress drag on unmount.
  React.useEffect(() => {
    return () => {
      dragCleanupRef.current?.();
    };
  }, []);

  const getDividerBounds = (dividerIndex: number, percents: number[]) => {
    const combined = percents[dividerIndex] + percents[dividerIndex + 1];
    return {min: minColumnPercent, max: combined - minColumnPercent};
  };

  const updatePanePair = React.useCallback(
    (dividerIndex: number, nextLeadingPercent: number) => {
      const current = panePercentsRef.current;
      const combined = current[dividerIndex] + current[dividerIndex + 1];
      const {min, max} = getDividerBounds(dividerIndex, current);
      const clamped = clamp(nextLeadingPercent, min, max);
      const next = [...current];
      next[dividerIndex] = clamped;
      next[dividerIndex + 1] = combined - clamped;
      panePercentsRef.current = next;
      setPanePercents(next);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [minColumnPercent],
  );

  const handleMouseDown = React.useCallback(
    (dividerIndex: number) => (event: React.MouseEvent<HTMLDivElement>) => {
      event.preventDefault();
      const startX = event.clientX;
      const startLeadingPercent = panePercentsRef.current[dividerIndex];
      const container = containerRef.current;
      if (!container) return;
      const {width} = container.getBoundingClientRect();
      if (width <= 0) return;

      const onMouseMove = (e: MouseEvent) => {
        const deltaPercent = ((e.clientX - startX) / width) * 100;
        updatePanePair(dividerIndex, startLeadingPercent + deltaPercent);
      };
      const onMouseUp = () => {
        window.removeEventListener("mousemove", onMouseMove);
        window.removeEventListener("mouseup", onMouseUp);
        dragCleanupRef.current = null;
      };

      dragCleanupRef.current?.();
      window.addEventListener("mousemove", onMouseMove);
      window.addEventListener("mouseup", onMouseUp);
      dragCleanupRef.current = () => {
        window.removeEventListener("mousemove", onMouseMove);
        window.removeEventListener("mouseup", onMouseUp);
      };
    },
    [updatePanePair],
  );

  const handleKeyDown = React.useCallback(
    (dividerIndex: number) => (event: React.KeyboardEvent<HTMLDivElement>) => {
      const {min, max} = getDividerBounds(
        dividerIndex,
        panePercentsRef.current,
      );
      const current = panePercentsRef.current[dividerIndex];
      switch (event.key) {
        case "ArrowLeft":
          event.preventDefault();
          updatePanePair(dividerIndex, current + (event.shiftKey ? -10 : -2));
          break;
        case "ArrowRight":
          event.preventDefault();
          updatePanePair(dividerIndex, current + (event.shiftKey ? 10 : 2));
          break;
        case "Home":
          event.preventDefault();
          updatePanePair(dividerIndex, min);
          break;
        case "End":
          event.preventDefault();
          updatePanePair(dividerIndex, max);
          break;
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [updatePanePair],
  );

  if (count === 0) return null;

  return (
    <div
      ref={containerRef}
      data-pihanga={cardName}
      className={clsx("pi-resizable-columns", className)}
    >
      {columnCards.map((card, i) => {
        const pct = panePercents[i] ?? 100 / count;
        return (
          <React.Fragment key={i}>
            {i > 0 && (
              <div
                className={clsx(
                  "pi-resizable-columns-divider",
                  dividerClassName,
                )}
                onMouseDown={handleMouseDown(i - 1)}
                onKeyDown={handleKeyDown(i - 1)}
                role="separator"
                aria-orientation="vertical"
                aria-label={`Resize columns ${i} and ${i + 1}`}
                aria-valuemin={minColumnPercent}
                aria-valuemax={
                  (panePercents[i - 1] ?? 0) +
                  (panePercents[i] ?? 0) -
                  minColumnPercent
                }
                aria-valuenow={Math.round(panePercents[i - 1] ?? 0)}
                tabIndex={0}
              />
            )}
            <div
              className="pi-resizable-columns-pane"
              style={{width: `${pct}%`}}
            >
              <Card cardName={card} parentCard={cardName} />
            </div>
          </React.Fragment>
        );
      })}
    </div>
  );
};

/*
 * ResizableColumns layout
 *
 * Divider styling options
 * ──────────────────────
 * Each drag handle is an 8 px flex-shrink-0 item (`::before` carries the visible line).
 *
 * 1. CSS custom properties (set on the container or globally):
 *      --rg-divider-color       default background of the 1 px line
 *      --rg-divider-hover-color background on hover / focus
 *      --rg-divider-width       default line thickness (default 1px)
 *      --rg-divider-hover-width line thickness on hover / focus (default 4px)
 *
 * 2. Override with `dividerClassName` prop — targets the 8 px hit-area element.
 *    Use `[&::before]:bg-primary` (Tailwind arbitrary modifier) to reach the inner line:
 *      dividerClassName="[&::before]:bg-primary [&::before]:w-[2px]"
 *
 * 3. Cell borders — apply a `border` class *inside* each child card.
 *    This is the only option for 'auto' columns (no divider element exists there).
 */

.pi-resizable-columns {
  display: flex;
  flex-direction: row;
  width: 100%;
  min-height: 100%;
  overflow: hidden;
}

/* Each column pane — width is set via inline style from the component */
.pi-resizable-columns-pane {
  overflow: hidden;
  min-width: 0;
  flex-shrink: 0;
}

/* ── Drag handle between columns ─────────────────────────────────────────── */

.pi-resizable-columns-divider {
  flex: 0 0 8px;
  cursor: col-resize;
  position: relative;
}

.pi-resizable-columns-divider::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: var(--rg-divider-width, 1px);
  background-color: var(--rg-divider-color, hsl(var(--border, 214 32% 91%)));
  transition: width 120ms ease, background-color 120ms ease;
}

.pi-resizable-columns-divider:hover::before,
.pi-resizable-columns-divider:focus-visible::before {
  width: var(--rg-divider-hover-width, 4px);
  background-color: var(--rg-divider-hover-color,
      hsl(var(--muted-foreground, 215 16% 47%)));
}

import {createCardDeclaration, type PiCardRef} from "@pihanga2/core";

export const RESIZABLE_COLUMNS_CARD = "pi/resizable-columns";

export type ResizableColumnsProps = {
  columnCards: PiCardRef[];
  /**
   * Initial column widths. Supports CSS-like values:
   *   - '200px'  — fixed initial width
   *   - '30%'    — explicit percentage
   *   - '1fr'    — fraction of remaining space (after px/% columns)
   *
   * Defaults to equal split when omitted or when length doesn't match columnCards.
   * @example ['200px', '1fr', '1fr']  — fixed sidebar, two equal remaining columns
   * @example ['30%', '70%']
   * @example ['1fr', '2fr', '1fr']
   */
  columnWidths?: string[];
  /** Minimum percentage any column can shrink to during drag. Default: 10 */
  minColumnPercent?: number;
  className?: string;
  dividerClassName?: string;
};

export const ResizableColumns = createCardDeclaration<ResizableColumnsProps>(
  RESIZABLE_COLUMNS_CARD,
);
